import { Component, effect, input, output, signal } from '@angular/core';
import {
  CampoClave,
  camposParaPut,
  formCompleto,
  formDesdeIdea,
} from '../../services/my-idea-fields';
import { Idea, IdeaFields } from '../../../../shared/types/models';

/**
 * Manual edit form for the 6 idea fields (T-047 / T-075, RNF-9).
 *
 * Renders the 6 editable fields (the single structured one — proponent — is
 * decomposed into its simple parts), validates completeness and emits the
 * compiled 6-field payload for the PUT. While the
 * idea is being generated by the IA the form is disabled (RNF-9), mirroring
 * the backend 409. The draft survives a same-idea reload (e.g. after an
 * improve round) and only resets when a different idea is loaded. UI copy in
 * Spanish (RNF-4).
 */
@Component({
  selector: 'app-field-editor',
  templateUrl: './field-editor.html',
})
export class FieldEditor {
  /** The idea being edited (drives the prefill and the generation block). */
  readonly idea = input.required<Idea>();
  /** Emits the compiled 6-field payload when the form is complete and valid. */
  readonly guardado = output<IdeaFields>();

  protected readonly form = signal<IdeaFields | null>(null);
  protected readonly deshabilitado = signal(false);
  protected readonly avisoError = signal('');
  protected readonly completo = formCompleto;
  private ideaCargada = '';

  constructor() {
    // Prefills the draft once the inputs bind, and re-blocks the form every
    // time the generation flag flips. A same-idea reload keeps the user's
    // in-progress draft; a new idea resets it.
    effect(() => {
      const idea = this.idea();
      if (idea.id !== this.ideaCargada) {
        this.ideaCargada = idea.id;
        this.form.set(formDesdeIdea(idea));
      }
      this.deshabilitado.set(idea.generando);
    });
  }

  protected cambiarTexto(clave: CampoClave, valor: string): void {
    this.form.update((f) => (f ? { ...f, [clave]: valor } : f));
  }

  protected cambiarProponente(campo: 'name' | 'area' | 'contact', valor: string): void {
    this.form.update((f) => (f ? { ...f, proponent: { ...f.proponent, [campo]: valor } } : f));
  }

  protected notificar(): void {
    if (this.deshabilitado()) return;
    const f = this.form();
    if (!f) return;
    if (!this.completo(f)) {
      this.avisoError.set('Completa todos los campos antes de guardar.');
      return;
    }
    this.avisoError.set('');
    this.guardado.emit(camposParaPut(f));
  }

  protected vaciarAviso(): void {
    this.avisoError.set('');
  }
}
